static bool obj_put(Value*o,char*k,Value*v,int line,EsError*e){for(size_t i=0;i<o->u.obj.n;i++)if(!strcmp(o->u.obj.v[i].key,k)){es_error(e,3,line,"duplicate decoded key");return false;}if(o->u.obj.n==o->u.obj.cap){size_t nc=o->u.obj.cap?o->u.obj.cap*2:8;VPair*q=es_realloc(o->u.obj.v,nc*sizeof*q,e);if(!q)return false;o->u.obj.v=q;o->u.obj.cap=nc;}o->u.obj.v[o->u.obj.n++]=(VPair){k,v,line};return true;}
static bool hex4(JP*p,uint32_t*out){if(p->i+4>p->n)return false;uint32_t v=0;for(int k=0;k<4;k++){unsigned c=p->s[p->i++];int x;if(c>='0'&&c<='9')x=c-'0';else if(c>='a'&&c<='f')x=c-'a'+10;else if(c>='A'&&c<='F')x=c-'A'+10;else return false;v=(v<<4)|(unsigned)x;}*out=v;return true;}
static bool sb_add(char**b,size_t*n,size_t*cap,const unsigned char*p,size_t m,EsError*e){if(*n+m+1>*cap){size_t nc=*cap?*cap:32;while(nc<*n+m+1){if(nc>SIZE_MAX/2){es_error(e,8,0,"string too large");return false;}nc*=2;}char*q=es_realloc(*b,nc,e);if(!q)return false;*b=q;*cap=nc;}memcpy(*b+*n,p,m);*n+=m;(*b)[*n]=0;return true;}
static bool utf8_enc(uint32_t cp,unsigned char out[4],size_t*nn){if(cp<=0x7f){out[0]=(unsigned char)cp;*nn=1;}else if(cp<=0x7ff){out[0]=0xc0|(cp>>6);out[1]=0x80|(cp&63);*nn=2;}else if(cp<=0xffff){out[0]=0xe0|(cp>>12);out[1]=0x80|((cp>>6)&63);out[2]=0x80|(cp&63);*nn=3;}else if(cp<=0x10ffff){out[0]=0xf0|(cp>>18);out[1]=0x80|((cp>>12)&63);out[2]=0x80|((cp>>6)&63);out[3]=0x80|(cp&63);*nn=4;}else return false;return true;}
static char*jstring(JP*p){int line=p->line;if(p->s[p->i++]!='"')return NULL;char*b=NULL;size_t n=0,cap=0;while(p->i<p->n){unsigned c=p->s[p->i++];if(c=='"'){if(!b)b=es_strdup("",p->e);if(!b)return NULL;if(!es_utf8_valid((unsigned char*)b,n,true)){free(b);es_error(p->e,3,line,"invalid UTF-8 or NUL in string");return NULL;}return b;}if(c<0x20){free(b);es_error(p->e,3,p->line,"unescaped control byte in string");return NULL;}if(c=='\\'){if(p->i>=p->n){free(b);es_error(p->e,3,p->line,"truncated escape");return NULL;}unsigned q=p->s[p->i++],one=0;switch(q){case '"':one='"';break;case '\\':one='\\';break;case '/':one='/';break;case 'b':one='\b';break;case 'f':one='\f';break;case 'n':one='\n';break;case 'r':one='\r';break;case 't':one='\t';break;case 'u':{uint32_t cp;if(!hex4(p,&cp)){free(b);es_error(p->e,3,p->line,"bad unicode escape");return NULL;}if(cp>=0xd800&&cp<=0xdbff){if(p->i+2>p->n||p->s[p->i++]!='\\'||p->s[p->i++]!='u'){free(b);es_error(p->e,3,p->line,"high surrogate without low surrogate");return NULL;}uint32_t lo;if(!hex4(p,&lo)||lo<0xdc00||lo>0xdfff){free(b);es_error(p->e,3,p->line,"invalid low surrogate");return NULL;}cp=0x10000+((cp-0xd800)<<10)+(lo-0xdc00);}else if(cp>=0xdc00&&cp<=0xdfff){free(b);es_error(p->e,3,p->line,"unpaired low surrogate");return NULL;}if(cp==0){free(b);es_error(p->e,3,p->line,"decoded NUL not permitted");return NULL;}unsigned char u[4];size_t un;if(!utf8_enc(cp,u,&un)||!sb_add(&b,&n,&cap,u,un,p->e)){free(b);return NULL;}continue;}default:free(b);es_error(p->e,3,p->line,"unknown escape");return NULL;}unsigned char z=(unsigned char)one;if(!sb_add(&b,&n,&cap,&z,1,p->e)){free(b);return NULL;}}else{unsigned char z=(unsigned char)c;if(!sb_add(&b,&n,&cap,&z,1,p->e)){free(b);return NULL;}}}free(b);es_error(p->e,3,line,"unterminated string");return NULL;}
