static Value*jarr(JP*p,int d){if(d>ES_MAX_DEPTH){es_error(p->e,3,p->line,"nesting exceeds 128");return NULL;}int l=p->line;p->i++;Value*a=value_new(V_ARR,l,p->e);if(!a)return NULL;jws(p);if(p->i<p->n&&p->s[p->i]==']'){p->i++;return a;}for(;;){Value*v=jval(p,d+1);if(!v){value_free(a);return NULL;}if(!arr_push(a,v,p->e)){value_free(v);value_free(a);return NULL;}jws(p);if(p->i>=p->n){value_free(a);es_error(p->e,3,p->line,"unterminated array");return NULL;}unsigned c=p->s[p->i++];if(c==']')return a;if(c!=','){value_free(a);es_error(p->e,3,p->line,"expected ',' or ']'");return NULL;}jws(p);if(p->i<p->n&&p->s[p->i]==']'){value_free(a);es_error(p->e,3,p->line,"trailing comma");return NULL;}}}
static Value*jobj(JP*p,int d){if(d>ES_MAX_DEPTH){es_error(p->e,3,p->line,"nesting exceeds 128");return NULL;}int l=p->line;p->i++;Value*o=value_new(V_OBJ,l,p->e);if(!o)return NULL;jws(p);if(p->i<p->n&&p->s[p->i]=='}'){p->i++;return o;}for(;;){jws(p);if(p->i>=p->n||p->s[p->i]!='"'){value_free(o);es_error(p->e,3,p->line,"object key must be string");return NULL;}int kl=p->line;char*k=jstring(p);if(!k){value_free(o);return NULL;}jws(p);if(p->i>=p->n||p->s[p->i++]!=':'){free(k);value_free(o);es_error(p->e,3,p->line,"expected ':'");return NULL;}Value*v=jval(p,d+1);if(!v){free(k);value_free(o);return NULL;}if(!obj_put(o,k,v,kl,p->e)){free(k);value_free(v);value_free(o);return NULL;}jws(p);if(p->i>=p->n){value_free(o);es_error(p->e,3,p->line,"unterminated object");return NULL;}unsigned c=p->s[p->i++];if(c=='}')return o;if(c!=','){value_free(o);es_error(p->e,3,p->line,"expected ',' or '}'");return NULL;}jws(p);if(p->i<p->n&&p->s[p->i]=='}'){value_free(o);es_error(p->e,3,p->line,"trailing comma");return NULL;}}}
static bool jnumlex(const unsigned char*s,size_t n,size_t*len,bool*isint){size_t i=0;if(i<n&&s[i]=='-')i++;if(i>=n)return false;if(s[i]=='0'){i++;if(i<n&&isdigit(s[i]))return false;}else if(s[i]>='1'&&s[i]<='9')while(i<n&&isdigit(s[i]))i++;else return false;bool ii=true;if(i<n&&s[i]=='.'){ii=false;i++;if(i>=n||!isdigit(s[i]))return false;while(i<n&&isdigit(s[i]))i++;}if(i<n&&(s[i]=='e'||s[i]=='E')){ii=false;i++;if(i<n&&(s[i]=='+'||s[i]=='-'))i++;if(i>=n||!isdigit(s[i]))return false;while(i<n&&isdigit(s[i]))i++;}*len=i;*isint=ii;return true;}
static Value*jval(JP*p,int d){jws(p);if(p->i>=p->n){es_error(p->e,3,p->line,"expected value");return NULL;}unsigned c=p->s[p->i];if(c=='{')return jobj(p,d);if(c=='[')return jarr(p,d);if(c=='"'){int l=p->line;char*s=jstring(p);if(!s)return NULL;Value*v=value_new(V_STR,l,p->e);if(!v){free(s);return NULL;}v->u.s=s;return v;}if(p->i+4<=p->n&&!memcmp(p->s+p->i,"true",4)){p->i+=4;Value*v=value_new(V_BOOL,p->line,p->e);if(v)v->u.b=true;return v;}if(p->i+5<=p->n&&!memcmp(p->s+p->i,"false",5)){p->i+=5;Value*v=value_new(V_BOOL,p->line,p->e);if(v)v->u.b=false;return v;}if(p->i+4<=p->n&&!memcmp(p->s+p->i,"null",4)){p->i+=4;return value_new(V_NULL,p->line,p->e);}if(c=='-'||isdigit(c)){size_t ln;bool ii;if(!jnumlex(p->s+p->i,p->n-p->i,&ln,&ii)){es_error(p->e,3,p->line,"invalid number");return NULL;}int l=p->line;char*lex=es_strndup((char*)p->s+p->i,ln,p->e);if(!lex)return NULL;p->i+=ln;if(ii){Value*v=value_new(V_INT,l,p->e);if(!v){free(lex);return NULL;}v->u.s=lex;return v;}errno=0;char*ep=NULL;double x=strtod(lex,&ep);bool bad=(errno==ERANGE||!ep||*ep||!isfinite(x));free(lex);if(bad){es_error(p->e,3,l,"number not finite/representable");return NULL;}Value*v=value_new(V_NUM,l,p->e);if(v)v->u.num=x;return v;}es_error(p->e,3,p->line,"unexpected token");return NULL;}
bool parse_json_bytes(const unsigned char*d,size_t n,Value**out,EsError*e){*out=NULL;if(!es_utf8_valid(d,n,false)){es_error(e,3,1,"invalid UTF-8 input");return false;}JP p={d,n,0,1,e};jws(&p);Value*v=jval(&p,1);if(!v)return false;jws(&p);if(p.i!=n){value_free(v);es_error(e,3,p.line,"trailing data");return false;}*out=v;return true;}
