typedef struct{char*txt;int indent,line;}YLine;typedef struct{YLine*l;size_t n,i;EsError*e;}YP;static char*trim(char*s){while(*s==' ')s++;size_t n=strlen(s);while(n&&s[n-1]==' ')s[--n]=0;return s;}static bool y_plain_int(const char*s){if(*s=='+'||*s=='-')s++;if(!*s)return false;while(*s)if(!isdigit((unsigned char)*s++))return false;return true;}static bool y_num(const char*s){const char*p=s;if(*p=='+'||*p=='-')p++;bool left=false,right=false,dot=false,ex=false;while(isdigit((unsigned char)*p)){left=true;p++;}if(*p=='.'){dot=true;p++;while(isdigit((unsigned char)*p)){right=true;p++;}if(!left&&!right)return false;}if(*p=='e'||*p=='E'){ex=true;p++;if(*p=='+'||*p=='-')p++;bool ed=false;while(isdigit((unsigned char)*p)){ed=true;p++;}if(!ed)return false;}return !*p&&(dot||ex)&&(left||right);}static int cieq(const char*a,const char*b){while(*a&&*b){if(tolower((unsigned char)*a++)!=tolower((unsigned char)*b++))return 0;}return !*a&&!*b;}
static char*y_unquote(const char*s,int line,EsError*e){size_t len=strlen(s);if(len<2||s[len-1]!=s[0]){es_error(e,3,line,"unterminated quoted scalar");return NULL;}if(s[0]=='"'){JP p={(const unsigned char*)s,len,0,line,e};char*b=jstring(&p);if(!b)return NULL;if(p.i!=len){free(b);es_error(e,3,line,"bad quoted scalar");return NULL;}return b;}char*b=NULL;size_t n=0,cap=0;for(size_t i=1;i+1<len;i++){unsigned char c=(unsigned char)s[i];if(c=='\''&&i+1<len-1&&s[i+1]=='\'')i++;else if(c=='\''){free(b);es_error(e,3,line,"bad single quote");return NULL;}if(!sb_add(&b,&n,&cap,&c,1,e)){free(b);return NULL;}}if(!b)b=es_strdup("",e);return b;}
static char*find_colon(char*s){bool sq=false,dq=false,esc=false;int br=0,bc=0;for(char*p=s;*p;p++){if(dq){if(esc)esc=false;else if(*p=='\\')esc=true;else if(*p=='"')dq=false;continue;}if(sq){if(*p=='\''&&p[1]=='\''){p++;continue;}if(*p=='\'')sq=false;continue;}if(*p=='"')dq=true;else if(*p=='\'')sq=true;else if(*p=='[')br++;else if(*p==']')br--;else if(*p=='{')bc++;else if(*p=='}')bc--;else if(*p==':'&&!br&&!bc&&(p[1]==0||isspace((unsigned char)p[1])))return p;}return NULL;}
