static Value*y_flow(const char*s,int line,EsError*e){size_t len=strlen(s);char open=s[0],close=open=='['?']':'}';if(len<2||s[len-1]!=close){es_error(e,3,line,"malformed flow container");return NULL;}Value*v=value_new(open=='['?V_ARR:V_OBJ,line,e);if(!v)return NULL;char*tmp=es_strndup(s+1,len-2,e);if(!tmp){value_free(v);return NULL;}char*p=tmp;while(1){p=trim(p);if(!*p)break;bool sq=false,dq=false,esc=false;char*comma=NULL;for(char*q=p;*q;q++){if(dq){if(esc)esc=false;else if(*q=='\\')esc=true;else if(*q=='"')dq=false;}else if(sq){if(*q=='\''&&q[1]=='\'')q++;else if(*q=='\'')sq=false;}else if(*q=='"')dq=true;else if(*q=='\'')sq=true;else if(*q=='['||*q=='{'||*q==']'||*q=='}'){free(tmp);value_free(v);es_error(e,3,line,"nested flow containers unsupported");return NULL;}else if(*q==','){comma=q;break;}}char*next=NULL;if(comma){*comma=0;next=comma+1;}char*item=trim(p);if(v->type==V_ARR){Value*x=y_scalar(item,line,e);if(!x||!arr_push(v,x,e)){if(x)value_free(x);free(tmp);value_free(v);return NULL;}}else{char*c=find_colon(item);if(!c){free(tmp);value_free(v);es_error(e,3,line,"flow map requires key:value");return NULL;}*c=0;char*ks=trim(item),*vs=trim(c+1);char*k;if(*ks=='\''||*ks=='"')k=y_unquote(ks,line,e);else k=es_strdup(ks,e);Value*x=y_scalar(vs,line,e);if(!k||!x||!obj_put(v,k,x,line,e)){free(k);if(x)value_free(x);free(tmp);value_free(v);return NULL;}}if(!next)break;p=next;if(!*trim(p)){free(tmp);value_free(v);es_error(e,3,line,"trailing flow comma");return NULL;}}free(tmp);return v;}
static Value*y_scalar(const char*in,int line,EsError*e){char*s=es_strdup(in,e);if(!s)return NULL;char*t=trim(s);if(!*t){free(s);es_error(e,3,line,"missing scalar");return NULL;}if(t[0]=='['||t[0]=='{'){Value*v=y_flow(t,line,e);free(s);return v;}if(t[0]=='\''||t[0]=='"'){char*q=y_unquote(t,line,e);free(s);if(!q)return NULL;Value*v=value_new(V_STR,line,e);if(v)v->u.s=q;else free(q);return v;}if(!strcmp(t,"~")||cieq(t,"null")){free(s);return value_new(V_NULL,line,e);}if(cieq(t,"true")||cieq(t,"false")){Value*v=value_new(V_BOOL,line,e);if(v)v->u.b=cieq(t,"true");free(s);return v;}if(y_plain_int(t)){Value*v=value_new(V_INT,line,e);if(v)v->u.s=es_strdup(t,e);free(s);return v;}if(y_num(t)){errno=0;char*ep;double d=strtod(t,&ep);if(errno==ERANGE||!isfinite(d)||*ep){free(s);es_error(e,3,line,"invalid YAML number");return NULL;}Value*v=value_new(V_NUM,line,e);if(v)v->u.num=d;free(s);return v;}if(strstr(t,": ")){free(s);es_error(e,3,line,"plain scalar containing ': ' must be quoted");return NULL;}Value*v=value_new(V_STR,line,e);if(v)v->u.s=es_strdup(t,e);free(s);return v;}
