static Value*y_block(YP*p,int indent,int depth,bool force_seq){if(depth>ES_MAX_DEPTH){es_error(p->e,3,p->i<p->n?p->l[p->i].line:0,"nesting exceeds 128");return NULL;}if(p->i>=p->n)return NULL;bool seq=force_seq||(p->l[p->i].indent==indent&&p->l[p->i].txt[0]=='-'&&(p->l[p->i].txt[1]==0||p->l[p->i].txt[1]==' '));Value*r=value_new(seq?V_ARR:V_OBJ,p->l[p->i].line,p->e);if(!r)return NULL;while(p->i<p->n){YLine*ln=&p->l[p->i];if(ln->indent<indent)break;if(ln->indent>indent){value_free(r);es_error(p->e,3,ln->line,"unexpected indentation");return NULL;}if(seq){if(ln->txt[0]!='-'||(ln->txt[1]&&ln->txt[1]!=' '))break;char*rest=trim(ln->txt+1);int line=ln->line;p->i++;Value*item=NULL;if(!*rest){if(p->i>=p->n||p->l[p->i].indent<=indent){value_free(r);es_error(p->e,3,line,"bare sequence item missing child");return NULL;}item=y_block(p,p->l[p->i].indent,depth+1,false);}else{char*col=find_colon(rest);if(col){item=value_new(V_OBJ,line,p->e);if(!item){value_free(r);return NULL;}*col=0;char*k=y_key(rest,line,p->e),*val=trim(col+1);Value*x=NULL;if(!k){value_free(item);value_free(r);return NULL;}if(*val)x=y_scalar(val,line,p->e);else{if(p->i>=p->n||p->l[p->i].indent<=indent){free(k);value_free(item);value_free(r);es_error(p->e,3,line,"mapping key missing child");return NULL;}x=y_block(p,p->l[p->i].indent,depth+1,false);}if(!x||!obj_put(item,k,x,line,p->e)){free(k);if(x)value_free(x);value_free(item);value_free(r);return NULL;}int child=-1;while(p->i<p->n&&p->l[p->i].indent>indent){if(child<0)child=p->l[p->i].indent;if(p->l[p->i].indent!=child)break;char*cc=find_colon(p->l[p->i].txt);if(!cc)break;int l2=p->l[p->i].line;*cc=0;char*k2=y_key(p->l[p->i].txt,l2,p->e),*v2=trim(cc+1);p->i++;Value*x2=NULL;if(*v2)x2=y_scalar(v2,l2,p->e);else{if(p->i>=p->n||p->l[p->i].indent<=child){free(k2);value_free(item);value_free(r);es_error(p->e,3,l2,"missing child");return NULL;}x2=y_block(p,p->l[p->i].indent,depth+1,false);}if(!k2||!x2||!obj_put(item,k2,x2,l2,p->e)){free(k2);if(x2)value_free(x2);value_free(item);value_free(r);return NULL;}}}else item=y_scalar(rest,line,p->e);}if(!item||!arr_push(r,item,p->e)){if(item)value_free(item);value_free(r);return NULL;}}else{if(ln->txt[0]=='-'&&(ln->txt[1]==0||ln->txt[1]==' '))break;char*col=find_colon(ln->txt);if(!col){value_free(r);es_error(p->e,3,ln->line,"expected mapping entry");return NULL;}*col=0;char*k=y_key(ln->txt,ln->line,p->e),*val=trim(col+1);int line=ln->line;p->i++;Value*x=NULL;if(*val)x=y_scalar(val,line,p->e);else{if(p->i>=p->n){free(k);value_free(r);es_error(p->e,3,line,"mapping key missing child");return NULL;}if(p->l[p->i].indent==indent&&p->l[p->i].txt[0]=='-')x=y_block(p,indent,depth+1,true);else if(p->l[p->i].indent>indent)x=y_block(p,p->l[p->i].indent,depth+1,false);else{free(k);value_free(r);es_error(p->e,3,line,"mapping key missing child");return NULL;}}if(!k||!x||!obj_put(r,k,x,line,p->e)){free(k);if(x)value_free(x);value_free(r);return NULL;}}}return r;}
static bool yaml_lines(const unsigned char*d,size_t n,YLine**out,size_t*on,EsError*e){char*buf=es_malloc(n+1,e);if(!buf)return false;size_t j=0;for(size_t i=0;i<n;i++){if(d[i]=='\r'){if(i+1<n&&d[i+1]=='\n')continue;buf[j++]='\n';}else buf[j++]=(char)d[i];}buf[j]=0;size_t cap=64,cnt=0;YLine*l=es_malloc(cap*sizeof*l,e);if(!l){free(buf);return false;}char*cur=buf;int line=1;while(cur){char*nl=strchr(cur,'\n');if(nl)*nl=0;int ind=0;while(cur[ind]==' '||cur[ind]=='\t'){if(cur[ind]=='\t'){es_error(e,3,line,"tab indentation unsupported");goto fail;}ind++;}char*s=cur+ind;bool sq=false,dq=false,esc=false;for(char*p=s;*p;p++){if(dq){if(esc)esc=false;else if(*p=='\\')esc=true;else if(*p=='"')dq=false;}else if(sq){if(*p=='\''&&p[1]=='\'')p++;else if(*p=='\'')sq=false;}else if(*p=='"')dq=true;else if(*p=='\'')sq=true;else if(*p=='#'&&(p==s||isspace((unsigned char)p[-1]))){*p=0;break;}}size_t sl=strlen(s);while(sl&&s[sl-1]==' ')s[--sl]=0;if(*s){if(!strcmp(s,"---")||!strcmp(s,"...")||s[0]=='%'||s[0]=='?'||strstr(s,"<<:")||strstr(s," &")||strstr(s," *")||strchr(s,'!')){es_error(e,3,line,"unsupported YAML feature");goto fail;}char*c=find_colon(s);if(c){char*v=trim(c+1);if(*v=='|'||*v=='>'){es_error(e,3,line,"block scalar unsupported");goto fail;}}if(cnt==cap){cap*=2;YLine*q=es_realloc(l,cap*sizeof*l,e);if(!q)goto fail;l=q;}l[cnt]=(YLine){es_strdup(s,e),ind,line};if(!l[cnt].txt)goto fail;cnt++;}if(!nl)break;cur=nl+1;line++;}free(buf);*out=l;*on=cnt;return true;fail:for(size_t i=0;i<cnt;i++)free(l[i].txt);free(l);free(buf);return false;}
bool parse_yaml_bytes(const unsigned char*d,size_t n,Value**out,EsError*e){*out=NULL;if(!es_utf8_valid(d,n,false)){es_error(e,3,1,"invalid UTF-8 input");return false;}YLine*l=NULL;size_t ln=0;if(!yaml_lines(d,n,&l,&ln,e))return false;if(!ln){free(l);es_error(e,3,1,"empty YAML");return false;}YP p={l,ln,0,e};Value*v=y_block(&p,l[0].indent,1,false);if(!v){for(size_t i=0;i<ln;i++)free(l[i].txt);free(l);return false;}if(p.i!=ln){value_free(v);es_error(e,3,l[p.i].line,"invalid dedentation/container mix");for(size_t i=0;i<ln;i++)free(l[i].txt);free(l);return false;}for(size_t i=0;i<ln;i++)free(l[i].txt);free(l);*out=v;return true;}
bool parse_config_file_value(const char*path,Value**out,EsError*e){unsigned char*d;size_t n;if(!es_read_file(path,&d,&n,e,3))return false;size_t L=strlen(path);bool ok;if(L>=5&&!strcmp(path+L-5,".json"))ok=parse_json_bytes(d,n,out,e);else if((L>=5&&!strcmp(path+L-5,".yaml"))||(L>=4&&!strcmp(path+L-4,".yml")))ok=parse_yaml_bytes(d,n,out,e);else{es_error(e,3,0,"unsupported config extension");ok=false;}free(d);return ok;}
